export { DataTable } from './data-table';
export type { DataTableProps } from './data-table';
export { DataTableToolbar } from './data-table-toolbar';
export type { DataTableToolbarProps } from './data-table-toolbar';
export { DataTablePagination } from './data-table-pagination';
export type { DataTablePaginationProps } from './data-table-pagination';
export { DataTableColumnHeader } from './data-table-column-header';
export { DataTableColumnVisibility } from './data-table-column-visibility';
export { DataTableEmpty } from './data-table-empty';
export { useDataTable, DATA_TABLE_ACTIONS_COLUMN_ID } from './use-data-table';
export { formatCellValue, defaultCellFormatter } from './cell-formatters';
export { dataTableFeatures } from './table-features';
export type {
  DataTableCellRenderer,
  DataTableCellRenderers,
  DataTableColumn,
  DataTableColumnDef,
  DataTableErrors,
  DataTableHttpException,
  DataTableMeta,
  DataTableQuery,
  DataTableResponse,
  DataTableRowActions,
  DataTableRowActionsContext,
  DataTableState,
  DataTableOptions,
  DataTableVisitOptions,
  DataTableSelectionState,
} from './types';
export type { DataTableColumnMeta, DataTableFeatures } from './table-features';

import type { ReactNode } from 'react';
import type {
    CellContext,
    ColumnDef,
    ColumnFiltersState,
    ColumnVisibilityState,
    PaginationState,
    Row,
    RowData,
    RowSelectionState,
    SortingState,
} from '@tanstack/react-table';
import type { DataTableFeatures } from './table-features';

export interface DataTableColumn<TData extends RowData = Record<string, unknown>> {
    name: string;
    label: string;
    sortable: boolean;
    searchable: boolean;
    filterable: boolean;
    hidden: boolean;
    filter_type?: 'text' | 'select' | 'boolean' | 'date_range' | 'number_range' | 'multi_select' | null;
    filter_options?: Array<{ value: string | number; label: string }>;
    /** Custom cell formatter. Receives the cell context and returns a React node. */
    cell?: (info: CellContext<DataTableFeatures, TData, unknown>) => ReactNode;
}

/**
 * Renders the content of a single cell.
 *
 * The renderer receives the TanStack cell context, so the raw value is
 * available through `info.getValue()` and the row through `info.row.original`.
 */
export type DataTableCellRenderer<TData extends RowData = Record<string, unknown>> = (
    info: CellContext<DataTableFeatures, TData, unknown>
) => ReactNode;

/** Cell renderers keyed by the column name they belong to. */
export type DataTableCellRenderers<TData extends RowData = Record<string, unknown>> = Record<
    string,
    DataTableCellRenderer<TData>
>;

/** Context handed to the row actions renderer. */
export interface DataTableRowActionsContext<TData extends RowData = Record<string, unknown>> {
    /** The row the actions belong to. */
    row: TData;
    /** Zero based index of the row inside the current page. */
    rowIndex: number;
}

/** Renders the trailing actions cell of a row. */
export type DataTableRowActions<TData extends RowData = Record<string, unknown>> = (
    context: DataTableRowActionsContext<TData>
) => ReactNode;

/** Validation errors reported by the Inertia response. */
export type DataTableErrors = Record<string, string>;

/** The response of a failed request that answered with a 4xx or 5xx status. */
export interface DataTableHttpException {
    status: number;
    data: string | Record<string, unknown>;
    headers: Record<string, string>;
}

/**
 * Options forwarded to the underlying Inertia `router.visit` call.
 *
 * Only the options that make sense for a data table are exposed. Everything
 * else is intentionally left out to keep the public API small.
 */
export interface DataTableVisitOptions {
    /** Replace the current history entry instead of pushing a new one. */
    replace?: boolean;
    /** Keep the current scroll position. Defaults to `true`. */
    preserveScroll?: boolean;
    /** Keep the current component state. Defaults to `true`. */
    preserveState?: boolean;
    /** Props that should be requested on the partial reload. */
    only?: string[];
    /** Props that should be excluded from the partial reload. */
    except?: string[];
    /** Additional headers sent with the request. */
    headers?: Record<string, string>;
    /** Toggle the Inertia progress bar for these visits. */
    showProgress?: boolean;
    /** Called right before the request is sent. */
    onStart?: () => void;
    /** Called after the response was processed. */
    onFinish?: () => void;
    /** Called after a successful response. */
    onSuccess?: () => void;
    /** Called when the endpoint answered with validation errors. */
    onError?: (_errors: DataTableErrors) => void;
    /** Called when the endpoint answered with a 4xx or 5xx status. */
    onHttpException?: (_response: DataTableHttpException) => void;
    /** Called when the request could not be sent at all. */
    onNetworkError?: (_error: Error) => void;
}

export interface DataTableMeta {
    current_page: number;
    per_page: number;
    from: number | null;
    to: number | null;
    total: number;
    last_page: number;
}

export interface DataTableQuery {
    page: number;
    per_page: number;
    search: string;
    sort: Array<{ column: string; direction: string }>;
    searches: Array<{ column: string; value: string }>;
    filters: Array<{ column: string; value: unknown }>;
}

export interface DataTableQueryKeys {
    page: string;
    per_page: string;
    search: string;
    searches: string;
    sort: string;
    filters: string;
}

export interface DataTableConfig {
    debounce: number;
    per_page_options: number[];
    query_keys?: DataTableQueryKeys;
}

export interface DataTableResponse<TData extends RowData = Record<string, unknown>> {
    data: TData[];
    meta: DataTableMeta;
    query: DataTableQuery;
    columns: DataTableColumn<TData>[];
    config: DataTableConfig;
}

export interface DataTableState {
    page: number;
    perPage: number;
    search: string;
    sort: Array<{ column: string; direction: 'asc' | 'desc' }>;
    searches: Record<string, string>;
    filters: Record<string, unknown>;
}

export interface DataTableOptions<TData extends RowData = Record<string, unknown>> {
    data: DataTableResponse<TData>;
    onDataChange?: (_data: DataTableResponse<TData>) => void;
    /**
     * Optional explicit endpoint URL for the DataTable visits.
     *
     * When provided, the hook visits this URL instead of the current page's
     * pathname. Query parameters already present on the URL are preserved and
     * merged predictably with the DataTable query state (page, per-page,
     * search, column searches, filters and sorting). Consumers can pass a
     * Laravel Wayfinder generated URL, e.g. `index.url()`.
     *
     * The URL is resolved against the current origin (same-origin semantics):
     * only its pathname and query are used for the Inertia visit. Pass a path
     * such as `/users` or a same-origin absolute URL. When omitted, the current
     * page pathname is used, keeping the existing behaviour unchanged.
     */
    url?: string;
    dataPropName?: string;
    /**
     * Optional column definition overrides.
     *
     * Overrides are matched against the server provided columns by their `id`.
     * The server capabilities (`sortable`, `searchable`, `filterable`) stay
     * authoritative, an override may only disable them.
     */
    columns?: DataTableColumnDef<TData>[];
    /** Cell renderers keyed by column name. */
    cells?: DataTableCellRenderers<TData>;
    /** Renders a trailing actions cell for every row. */
    actions?: DataTableRowActions<TData>;
    /** Options forwarded to the Inertia `router.visit` call. */
    visitOptions?: DataTableVisitOptions;
    /** Derives a stable row id from the row data. */
    rowKey?: (_row: TData, _index: number) => string;
    /** Whether row selection is enabled, or a predicate receiving the row. */
    enableRowSelection?: boolean | ((row: Row<DataTableFeatures, TData>) => boolean);
    /** Callback fired when row selection changes. */
    onRowSelectionChange?: (_selection: RowSelectionState) => void;
}

export type DataTableColumnDef<TData extends RowData = Record<string, unknown>> = ColumnDef<
    DataTableFeatures,
    TData,
    unknown
>;

export type DataTableSortingState = SortingState;
export type DataTablePaginationState = PaginationState;
export type DataTableColumnFiltersState = ColumnFiltersState;
export type DataTableVisibilityState = ColumnVisibilityState;
export type DataTableSelectionState = RowSelectionState;

import {
    columnFilteringFeature,
    columnVisibilityFeature,
    globalFilteringFeature,
    metaHelper,
    rowPaginationFeature,
    rowSelectionFeature,
    rowSortingFeature,
    tableFeatures,
} from '@tanstack/react-table';

export interface DataTableColumnMeta {
    searchable?: boolean;
    filterable?: boolean;
    filter_type?: 'text' | 'select' | 'boolean' | 'date_range' | 'number_range' | 'multi_select' | null;
    filter_options?: Array<{ value: string | number; label: string }>;
    /**
     * Marks a column that only exists on the client (row actions, extra
     * client side columns). Those columns are never offered in the column
     * visibility menu because the server does not know about them.
     */
    client_only?: boolean;
}

export const dataTableFeatures = tableFeatures({
    columnFilteringFeature,
    columnVisibilityFeature,
    globalFilteringFeature,
    rowPaginationFeature,
    rowSelectionFeature,
    rowSortingFeature,
    columnMeta: metaHelper<DataTableColumnMeta>(),
});

export type DataTableFeatures = typeof dataTableFeatures;

'use client';

import { type ReactNode, forwardRef, type ReactElement, type Ref, useMemo } from 'react';
import { flexRender, type Row, type RowData, type RowSelectionState } from '@tanstack/react-table';
import {
    type DataTableCellRenderers,
    type DataTableColumnDef,
    type DataTableErrors,
    type DataTableResponse,
    type DataTableRowActions,
    type DataTableVisitOptions,
} from './types';
import { type DataTableFeatures } from './table-features';
import {
    Table,
    TableHeader,
    TableBody,
    TableRow,
    TableCell,
} from '@/components/ui/table';
import { Skeleton } from '@/components/ui/skeleton';
import { DataTableToolbar } from './data-table-toolbar';
import { DataTablePagination } from './data-table-pagination';
import { DataTableColumnHeader } from './data-table-column-header';
import { DataTableEmpty } from './data-table-empty';
import { useDataTable, DATA_TABLE_ACTIONS_COLUMN_ID } from './use-data-table';

export interface DataTableProps<TData extends RowData> {
    data: DataTableResponse<TData>;
    children?: ReactNode;
    dataPropName?: string;
    /** Column definition overrides, matched against the server columns by id. */
    columns?: DataTableColumnDef<TData>[];
    /** Cell renderers keyed by column name. */
    cells?: DataTableCellRenderers<TData>;
    /** Renders a trailing actions cell for every row. */
    actions?: DataTableRowActions<TData>;
    /** Extra content rendered next to the search field. */
    toolbar?: ReactNode;
    /** Action buttons rendered on the right side of the toolbar (e.g. "+ New", "Export", "View"). */
    toolbarActions?: ReactNode;
    /** Optional date range picker rendered in the top-right corner of the toolbar. */
    dateRange?: {
        from: string | null;
        to: string | null;
        onChange: (_range: { from: string | null; to: string | null }) => void;
    };
    /** Replaces the default empty state. */
    empty?: ReactNode;
    /** Derives a stable row id from the row data. */
    rowKey?: (_row: TData, _index: number) => string;
    /** Called when a row is clicked. */
    onRowClick?: (_row: TData, _index: number) => void;
    /** Whether row selection is enabled, or a predicate receiving the row. */
    enableRowSelection?: boolean | ((row: Row<DataTableFeatures, TData>) => boolean);
    /** Callback fired when row selection changes. */
    onRowSelectionChange?: (_selection: RowSelectionState) => void;
    /** Options forwarded to the Inertia `router.visit` call. */
    visitOptions?: DataTableVisitOptions;
    /**
     * Optional explicit endpoint URL for the DataTable visits.
     *
     * When provided, the table visits this URL instead of the current page's
     * pathname. Query parameters already present on the URL are preserved and
     * merged with the DataTable query state. Consumers can pass a Laravel
     * Wayfinder generated URL, e.g. `index.url()`. When omitted, the current
     * page pathname is used.
     */
    url?: string;
    /** Called when the endpoint answered with validation errors. */
    onError?: (_errors: DataTableErrors) => void;
    /** Number of skeleton rows rendered while a visit is in flight. */
    skeletonRows?: number;
}

const DataTableComponent = forwardRef<HTMLTableElement, DataTableProps<Record<string, unknown>>>(
    (
        {
            data,
            children,
            dataPropName = 'data',
            columns,
            cells,
            actions,
            toolbarActions,
            dateRange,
            toolbar,
            empty,
            rowKey,
            onRowClick,
            enableRowSelection,
            onRowSelectionChange,
            visitOptions,
            url,
            onError,
            skeletonRows = 5,
            ...props
        },
        ref
    ) => {
        const mergedVisitOptions = useMemo<DataTableVisitOptions>(
            () => ({
                ...visitOptions,
                onError: (errors: DataTableErrors) => {
                    visitOptions?.onError?.(errors);
                    onError?.(errors);
                },
            }),
            [visitOptions, onError]
        );

        const {
            table,
            handlePageChange,
            handlePerPageChange,
            handleSearchChange,
            handleColumnSearchChange,
            handleFilterChange,
            handleClearColumnFilter,
            handleResetFilters,
            isFiltered,
            state,
            perPageOptions,
            columnSearches,
            isLoading,
        } = useDataTable<Record<string, unknown>>({
            data,
            dataPropName,
            columns,
            cells,
            actions,
            visitOptions: mergedVisitOptions,
            url,
            rowKey,
            enableRowSelection,
            onRowSelectionChange,
        });

        const rows = table.getRowModel().rows;
        const visibleColumnCount = Math.max(
            1,
            table.getAllLeafColumns().filter((column) => column.getIsVisible()).length
        );

        return (
            <div className="space-y-4">
                <DataTableToolbar
                    table={table}
                    search={state.search}
                    onSearchChange={handleSearchChange}
                    isFiltered={isFiltered}
                    onReset={handleResetFilters}
                    filters={state.filters}
                    columnSearches={columnSearches}
                    onFilterChange={handleFilterChange}
                    onColumnSearchChange={handleColumnSearchChange}
                    onClearFilter={handleClearColumnFilter}
                    actions={toolbarActions}
                    dateRange={dateRange}
                >
                    {toolbar}
                </DataTableToolbar>
                <div className="relative w-full overflow-x-auto rounded-md border">
                    <Table ref={ref} className="w-full caption-bottom text-sm" aria-busy={isLoading} {...props}>
                        <TableHeader>
                            {table.getHeaderGroups().map((headerGroup) => (
                                <TableRow key={headerGroup.id}>
                                    {headerGroup.headers.map((header) => (
                                        <DataTableColumnHeader
                                            key={header.id}
                                            header={header}
                                            column={header.column}
                                        />
                                    ))}
                                </TableRow>
                            ))}
                        </TableHeader>
                        <TableBody>
                            {isLoading ? (
                                Array.from({ length: skeletonRows }).map((_, rowIndex) => (
                                    <TableRow key={`skeleton-${rowIndex}`}>
                                        {Array.from({ length: visibleColumnCount }).map((__, cellIndex) => (
                                            <TableCell key={cellIndex} className="p-4 align-middle">
                                                <Skeleton className="h-4 w-full" />
                                            </TableCell>
                                        ))}
                                    </TableRow>
                                ))
                            ) : rows.length === 0 ? (
                                <DataTableEmpty columns={visibleColumnCount}>
                                    {empty}
                                </DataTableEmpty>
                            ) : (
                                rows.map((row) => (
                                    <TableRow
                                        key={row.id}
                                        data-state={row.getIsSelected() ? 'selected' : undefined}
                                        role={onRowClick ? 'button' : undefined}
                                        tabIndex={onRowClick ? 0 : undefined}
                                        onClick={
                                            onRowClick
                                                ? (e) => {
                                                      const target = e.target as HTMLElement | null;
                                                      const interactive = target?.closest(
                                                          'a, button, input, select, textarea, [role="button"], [role="checkbox"], [role="menuitem"]'
                                                      );
                                                      if (interactive && interactive !== e.currentTarget) {
                                                          return;
                                                      }
                                                      onRowClick(row.original, row.index);
                                                  }
                                                : undefined
                                        }
                                        onKeyDown={
                                            onRowClick
                                                ? (e) => {
                                                      if (e.target === e.currentTarget && (e.key === 'Enter' || e.key === ' ')) {
                                                          e.preventDefault();
                                                          onRowClick(row.original, row.index);
                                                      }
                                                  }
                                                : undefined
                                        }
                                        className={
                                            onRowClick
                                                ? 'cursor-pointer border-b transition-colors hover:bg-muted/50 data-[state=selected]:bg-muted focus-visible:outline-none focus-visible:bg-muted/50'
                                                : 'border-b transition-colors hover:bg-muted/50 data-[state=selected]:bg-muted'
                                        }
                                    >
                                        {row.getVisibleCells().map((cell) => (
                                            <TableCell
                                                key={cell.id}
                                                className="p-4 align-middle"
                                                onClick={
                                                    cell.column.id === DATA_TABLE_ACTIONS_COLUMN_ID
                                                        ? (e) => e.stopPropagation()
                                                        : undefined
                                                }
                                            >
                                                {flexRender(cell.column.columnDef.cell!, cell.getContext())}
                                            </TableCell>
                                        ))}
                                    </TableRow>
                                ))
                            )}
                        </TableBody>
                    </Table>
                </div>
                <DataTablePagination
                    currentPage={state.page}
                    perPage={state.perPage}
                    onPageChange={handlePageChange}
                    onPerPageChange={handlePerPageChange}
                    perPageOptions={perPageOptions}
                    totalPages={data.meta.last_page}
                    totalItems={data.meta.total}
                    selectedCount={table.getSelectedRowModel().rows.length}
                />
                {children}
            </div>
        );
    }
);

export const DataTable = Object.assign(
    DataTableComponent as <TData extends RowData>(
        props: DataTableProps<TData> & { ref?: Ref<HTMLTableElement> }
    ) => ReactElement | null,
    { displayName: 'DataTable' }
);

'use client';

import React, { type ReactNode, useState, useMemo } from 'react';
import { type ReactTable, type RowData } from '@tanstack/react-table';
import type { DataTableColumnMeta, DataTableFeatures } from './table-features';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { DataTableColumnVisibility } from './data-table-column-visibility';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuTrigger,
    DropdownMenuSeparator,
    DropdownMenuLabel,
} from '@/components/ui/dropdown-menu';
import { Checkbox } from '@/components/ui/checkbox';

export interface DataTableToolbarProps<TData extends RowData = Record<string, unknown>> {
    table?: ReactTable<DataTableFeatures, TData>;
    search: string;
    onSearchChange: (_value: string) => void;
    perPage?: number;
    onPerPageChange?: (_value: number) => void;
    perPageOptions?: number[];
    isFiltered?: boolean;
    onReset?: () => void;
    children?: ReactNode;
    /** Active per-column filters keyed by column id. */
    filters?: Record<string, unknown>;
    /** Active per-column searches keyed by column id. */
    columnSearches?: Record<string, string>;
    /** Fired when a per-column filter value changes. */
    onFilterChange?: (_column: string, _value: unknown) => void;
    /** Fired when a per-column search value changes. */
    onColumnSearchChange?: (_column: string, _value: string) => void;
    /** Fired when a per-column filter or search is cleared. */
    onClearFilter?: (_column: string, _clearSearch: boolean) => void;
    /** Action buttons rendered on the right side of the toolbar (e.g. "+ New", "Export", "View"). */
    actions?: ReactNode;
    /** Optional date range picker rendered in the top-right corner of the toolbar. */
    dateRange?: {
        from: string | null;
        to: string | null;
        onChange: (_range: { from: string | null; to: string | null }) => void;
    };
}

interface ColumnFilterInfo {
    label: string;
    canSearch: boolean;
    canFilter: boolean;
    filterType: DataTableColumnMeta['filter_type'];
    filterOptions: Array<{ value: string | number; label: string }>;
}

interface DataTableFilterChipProps {
    columnId: string;
    label: string;
    filterValue: unknown;
    searchValue: string;
    filterType: DataTableColumnMeta['filter_type'];
    filterOptions: Array<{ value: string | number; label: string }>;
    canSearch: boolean;
    canFilter: boolean;
    onFilterChange: (_column: string, _value: unknown) => void;
    onColumnSearchChange: (_column: string, _value: string) => void;
    onClearFilter: (_column: string, _clearSearch: boolean) => void;
}

function isFilterActive(value: unknown): boolean {
    return value !== '' && value !== null && value !== undefined;
}

function filterValueCount(value: unknown): number {
    if (Array.isArray(value)) {
        return value.length;
    }
    return isFilterActive(value) ? 1 : 0;
}

export function DataTableFilterChip({
    columnId,
    label,
    filterValue,
    searchValue,
    filterType,
    filterOptions,
    canSearch,
    canFilter,
    onFilterChange,
    onColumnSearchChange,
    onClearFilter,
}: DataTableFilterChipProps) {
    const [menuOpen, setMenuOpen] = useState<boolean>(false);

    const activeCount = filterValueCount(filterValue) + (searchValue ? 1 : 0);

    const handleFilterSelect = (value: string | number) => {
        onFilterChange(columnId, value);
        setMenuOpen(false);
    };

    const handleFilterBooleanChange = (value: boolean) => {
        onFilterChange(columnId, value);
        setMenuOpen(false);
    };

    const handleFilterMultiSelectChange = (
        value: string | number,
        event?: Event,
    ) => {
        // Radix closes the dropdown on select by default; preventDefault keeps
        // the menu open so users can toggle several options in one go.
        event?.preventDefault();

        // A restored scalar (e.g. a single pre-selected option) is normalized
        // to a singleton array so toggling it removes rather than re-adds it.
        const current = Array.isArray(filterValue)
            ? [...filterValue]
            : filterValue !== '' && filterValue !== null && filterValue !== undefined
                ? [filterValue]
                : [];
        const isSelected = current.some((item) => filterValueMatches(item, value));
        const next = isSelected
            ? current.filter((item) => !filterValueMatches(item, value))
            : [...current, value];
        onFilterChange(columnId, next);
    };

    const handleFilterTextChange = (value: string) => {
        onFilterChange(columnId, value);
    };

    const handleColumnSearchChange = (value: string) => {
        onColumnSearchChange(columnId, value);
    };

    const handleClearFilter = () => {
        onClearFilter(columnId, Boolean(canSearch && searchValue));
        setMenuOpen(false);
    };

    // Compares a restored filter value (often a string from the query string)
    // against an option value (which may be a number for integer-backed enums).
    // Array values (multi-value filters) match when any member equals the option.
    const filterValueMatches = (current: unknown, optionValue: string | number): boolean => {
        const matches = (value: unknown): boolean => {
            if (value === optionValue) {
                return true;
            }
            if (typeof value === 'string' && typeof optionValue === 'number') {
                return value === String(optionValue);
            }
            if (typeof value === 'number' && typeof optionValue === 'string') {
                return String(value) === optionValue;
            }
            return false;
        };
        if (Array.isArray(current)) {
            return current.some((member) => matches(member));
        }
        return matches(current);
    };

    return (
        <DropdownMenu open={menuOpen} onOpenChange={setMenuOpen}>
            <DropdownMenuTrigger asChild>
                <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setMenuOpen((open) => !open)}
                    className="h-8 px-2.5 text-xs gap-1.5 text-foreground hover:bg-accent"
                    aria-haspopup="true"
                    aria-expanded={menuOpen}
                >
                    {activeCount > 0 ? `${label} • ${activeCount} selected` : label}
                </Button>
            </DropdownMenuTrigger>
            {menuOpen && (
                <DropdownMenuContent className="w-60 p-2" align="end" sideOffset={6}>
                <DropdownMenuLabel className="px-1 text-xs font-semibold text-muted-foreground">
                    Filter {label}
                </DropdownMenuLabel>
                <DropdownMenuSeparator />

                {canSearch && (
                    <div className="p-1 space-y-1.5">
                        <label
                            className="block text-[11px] font-medium text-muted-foreground"
                            htmlFor={`toolbar-column-search-${columnId}`}
                        >
                            Search {label}
                        </label>
                        <Input
                            id={`toolbar-column-search-${columnId}`}
                            placeholder={`Search ${label}...`}
                            onChange={(e: React.ChangeEvent<HTMLInputElement>) =>
                                handleColumnSearchChange(e.target.value)
                            }
                            value={searchValue}
                            className="h-7 text-xs"
                        />
                    </div>
                )}

                {canFilter && filterType === 'select' && filterOptions.length > 0 && (
                    <div className="space-y-0.5 p-1 max-h-[200px] overflow-y-auto">
                        {filterOptions.map((option) => (
                            <DropdownMenuItem
                                key={option.value}
                                onSelect={() => {
                                    handleFilterSelect(option.value);
                                }}
                                className={`flex items-center gap-2 px-2 py-1 text-xs rounded cursor-pointer ${
                                    filterValueMatches(filterValue, option.value)
                                        ? 'bg-primary/10 text-primary font-medium'
                                        : 'hover:bg-accent'
                                }`}
                            >
                                <Checkbox
                                    aria-label={option.label}
                                    checked={filterValueMatches(filterValue, option.value)}
                                    className="h-3.5 w-3.5"
                                />
                                <span className="truncate">{option.label}</span>
                            </DropdownMenuItem>
                        ))}
                    </div>
                )}

                {canFilter && filterType === 'boolean' && (
                    <div className="space-y-0.5 p-1">
                        <DropdownMenuItem
                            onSelect={() => {
                                handleFilterBooleanChange(true);
                            }}
                            className={`flex items-center gap-2 px-2 py-1 text-xs rounded cursor-pointer ${
                                filterValue === true ? 'bg-primary/10 text-primary font-medium' : 'hover:bg-accent'
                            }`}
                        >
                            <Checkbox
                                aria-label="Yes"
                                checked={filterValue === true}
                                className="h-3.5 w-3.5"
                            />
                            <span className="truncate">Yes</span>
                        </DropdownMenuItem>
                        <DropdownMenuItem
                            onSelect={() => {
                                handleFilterBooleanChange(false);
                            }}
                            className={`flex items-center gap-2 px-2 py-1 text-xs rounded cursor-pointer ${
                                filterValue === false ? 'bg-primary/10 text-primary font-medium' : 'hover:bg-accent'
                            }`}
                        >
                            <Checkbox
                                aria-label="No"
                                checked={filterValue === false}
                                className="h-3.5 w-3.5"
                            />
                            <span className="truncate">No</span>
                        </DropdownMenuItem>
                    </div>
                )}

                {canFilter && filterType === 'multi_select' && filterOptions.length > 0 && (
                    <div className="space-y-0.5 p-1 max-h-[200px] overflow-y-auto">
                        {filterOptions.map((option) => (
                            <DropdownMenuItem
                                key={option.value}
                                onSelect={(event) => {
                                    handleFilterMultiSelectChange(option.value, event);
                                }}
                                className={`flex items-center gap-2 px-2 py-1 text-xs rounded cursor-pointer ${
                                    filterValueMatches(filterValue, option.value)
                                        ? 'bg-primary/10 text-primary font-medium'
                                        : 'hover:bg-accent'
                                }`}
                            >
                                <Checkbox
                                    aria-label={option.label}
                                    checked={filterValueMatches(filterValue, option.value)}
                                    className="h-3.5 w-3.5"
                                />
                                <span className="truncate">{option.label}</span>
                            </DropdownMenuItem>
                        ))}
                    </div>
                )}

                {canFilter && (filterType === 'date_range' || filterType === 'number_range') && (
                    <div className="p-1 space-y-1.5">
                        <div className="grid grid-cols-2 gap-2">
                            {['from', 'to'].map((key) => (
                                <div key={key} className="flex flex-col gap-1">
                                    <label
                                        className="block text-[11px] font-medium text-muted-foreground"
                                        htmlFor={`toolbar-range-${columnId}-${key}`}
                                    >
                                        {key.charAt(0).toUpperCase() + key.slice(1)}
                                    </label>
                                    <Input
                                        id={`toolbar-range-${columnId}-${key}`}
                                        type={filterType === 'number_range' ? 'number' : 'date'}
                                        value={typeof filterValue === 'object' && filterValue !== null
                                            ? (() => {
                                                  const raw = (filterValue as Record<string, string>)[key] ?? '';
                                                  // A date-only input cannot display a time-bearing value such
                                                  // as "2026-02-15 10:00:00". Strip the time portion so the
                                                  // control shows a valid date while preserving the full bound.
                                                  return filterType === 'date_range' && typeof raw === 'string'
                                                      ? raw.split(/[ T]/)[0]
                                                      : raw;
                                              })()
                                            : ''}
                                        onChange={(e) => {
                                            const next = {
                                                ...(typeof filterValue === 'object' && filterValue !== null
                                                    ? (filterValue as Record<string, string>)
                                                    : {}),
                                            };
                                            if (e.target.value === '') {
                                                delete next[key];
                                            } else {
                                                next[key] = e.target.value;
                                            }
                                            onFilterChange(columnId, Object.keys(next).length > 0 ? next : '');
                                        }}
                                        className="h-7 text-xs"
                                        aria-label={key}
                                    />
                                </div>
                            ))}
                        </div>
                    </div>
                )}

                {canFilter && filterType === 'text' && (
                    <div className="p-1 space-y-1.5">
                        <label
                            className="block text-[11px] font-medium text-muted-foreground"
                            htmlFor={`toolbar-filter-value-${columnId}`}
                        >
                            Filter value
                        </label>
                        <Input
                            id={`toolbar-filter-value-${columnId}`}
                            aria-label={`Filter ${label} value`}
                            placeholder={`Filter ${label}...`}
                            value={typeof filterValue === 'string' ? filterValue : ''}
                            onChange={(e: React.ChangeEvent<HTMLInputElement>) =>
                                handleFilterTextChange(e.target.value)
                            }
                            className="h-7 text-xs"
                        />
                    </div>
                )}

                <DropdownMenuSeparator />
                <DropdownMenuItem
                    onClick={handleClearFilter}
                    className="text-xs text-destructive hover:bg-destructive/10 cursor-pointer font-medium px-2 py-1 rounded"
                >
                    Clear filter
                </DropdownMenuItem>
            </DropdownMenuContent>
            )}
        </DropdownMenu>
    );
}

export function DataTableToolbar<TData extends RowData = Record<string, unknown>>({
    table,
    search,
    onSearchChange,
    perPage,
    onPerPageChange,
    perPageOptions,
    isFiltered,
    onReset,
    children,
    filters = {},
    columnSearches = {},
    onFilterChange = () => {},
    onColumnSearchChange = () => {},
    onClearFilter = () => {},
    actions,
    dateRange,
}: DataTableToolbarProps<TData>) {
    // Column metadata (label, filter type, options) derived from the table so
    // each filter chip can render the matching dropdown controls.
    const columnMeta = useMemo<Map<string, ColumnFilterInfo>>(() => {
        const map = new Map<string, ColumnFilterInfo>();
        table?.getAllLeafColumns().forEach((column) => {
            const meta = column.columnDef.meta as DataTableColumnMeta | undefined;
            const header = column.columnDef.header;
            const label = typeof header === 'string' ? header : column.id;
            map.set(column.id, {
                label,
                canSearch: meta?.searchable === true,
                canFilter: meta?.filterable === true,
                filterType: meta?.filter_type ?? 'text',
                filterOptions: meta?.filter_options ?? [],
            });
        });
        return map;
    }, [table]);

    return (
        <div className="flex flex-wrap items-center justify-between gap-2">
            <div className="flex flex-1 flex-wrap items-center gap-2">
                <Input
                    placeholder="Search..."
                    value={search}
                    onChange={(e: React.ChangeEvent<HTMLInputElement>) => onSearchChange(e.target.value)}
                    className="h-8 w-full min-w-[150px] sm:w-[200px] lg:w-[250px]"
                    aria-label="Global search"
                />
                {isFiltered && onReset && (
                    <Button
                        variant="ghost"
                        size="sm"
                        onClick={onReset}
                        className="h-8 px-2 text-xs gap-1 lg:px-3 text-muted-foreground hover:text-foreground"
                        aria-label="Reset filters"
                    >
                        Reset
                        <svg
                            className="h-3.5 w-3.5"
                            xmlns="http://www.w3.org/2000/svg"
                            viewBox="0 0 24 24"
                            fill="none"
                            stroke="currentColor"
                            strokeWidth="2"
                            strokeLinecap="round"
                            strokeLinejoin="round"
                            aria-hidden="true"
                        >
                            <line x1="18" y1="6" x2="6" y2="18" />
                            <line x1="6" y1="6" x2="18" y2="18" />
                        </svg>
                    </Button>
                )}
                {/* Render a filter chip for every eligible column (searchable or
                   filterable), active or not. Active columns show their selected
                   count; inactive columns stay as an "add filter" entrypoint so
                   users can always start a new column filter or search. */}
                {Array.from(columnMeta.entries()).map(([columnId, info]) => {
                    if (!info.canSearch && !info.canFilter) {
                        return null;
                    }
                    return (
                        <DataTableFilterChip
                            key={columnId}
                            columnId={columnId}
                            label={info.label}
                            filterValue={filters[columnId]}
                            searchValue={columnSearches[columnId] ?? ''}
                            filterType={info.filterType}
                            filterOptions={info.filterOptions}
                            canSearch={info.canSearch}
                            canFilter={info.canFilter}
                            onFilterChange={onFilterChange}
                            onColumnSearchChange={onColumnSearchChange}
                            onClearFilter={onClearFilter}
                        />
                    );
                })}
                {children}
            </div>
            <div className="flex items-center gap-2">
                {table && <DataTableColumnVisibility table={table} />}
                {!table && perPage !== undefined && onPerPageChange && perPageOptions && perPageOptions.length > 0 && (
                    <div className="flex items-center gap-2">
                        <label htmlFor="per-page" className="text-sm text-muted-foreground whitespace-nowrap">
                            Show
                        </label>
                        <Select value={String(perPage)} onValueChange={(value: string) => onPerPageChange(Number(value))}>
                            <SelectTrigger id="per-page" className="h-8 w-[80px]">
                                <SelectValue placeholder="Per page" />
                            </SelectTrigger>
                            <SelectContent side="bottom">
                                {perPageOptions.map((option) => (
                                    <SelectItem key={String(option)} value={String(option)}>
                                        {option}
                                    </SelectItem>
                                ))}
                            </SelectContent>
                        </Select>
                        <span className="text-sm text-muted-foreground whitespace-nowrap">per page</span>
                    </div>
                )}
                {dateRange && (
                    <div className="flex items-center gap-2">
                        <label
                            htmlFor="toolbar-date-from"
                            className="text-sm text-muted-foreground whitespace-nowrap"
                        >
                            From
                        </label>
                        <Input
                            id="toolbar-date-from"
                            type="date"
                            value={dateRange.from ?? ''}
                            onChange={(e) => {
                                dateRange.onChange({
                                    from: e.target.value || null,
                                    to: dateRange.to,
                                });
                            }}
                            className="h-7 text-xs w-[120px]"
                            aria-label="Date range from"
                        />
                        <label
                            htmlFor="toolbar-date-to"
                            className="text-sm text-muted-foreground whitespace-nowrap"
                        >
                            To
                        </label>
                        <Input
                            id="toolbar-date-to"
                            type="date"
                            value={dateRange.to ?? ''}
                            onChange={(e) => {
                                dateRange.onChange({
                                    from: dateRange.from,
                                    to: e.target.value || null,
                                });
                            }}
                            className="h-7 text-xs w-[120px]"
                            aria-label="Date range to"
